"use strict";
const icons = {
  history:'<circle cx="10" cy="10" r="7.5"/><path d="M10 5.5V10l3 2"/>',
  spark:'<path d="m10 2 2.2 5.8L18 10l-5.8 2.2L10 18l-2.2-5.8L2 10l5.8-2.2Z"/>',
  sources:'<rect x="2" y="3" width="12" height="10" rx="2"/><path d="M6 16h12V7M6 6h4"/>',
  settings:'<path d="M3 5h14M3 10h14M3 15h14"/><circle cx="7" cy="5" r="2"/><circle cx="13" cy="10" r="2"/><circle cx="8" cy="15" r="2"/>',
  device:'<rect x="2" y="3" width="16" height="11" rx="1"/><path d="M7 18h6M10 14v4"/>',
  refresh:'<path d="M16.5 7A7 7 0 1 0 17 12M17 3v4h-4"/>',
  bookmark:'<path d="M5 2h10v16l-5-3-5 3Z"/>',
  search:'<circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/>',
  arrow:'<path d="m7 4 6 6-6 6"/>',
  close:'<path d="m5 5 10 10M15 5 5 15"/>',
  play:'<path d="m7 4 9 6-9 6Z"/>',
  check:'<path d="m4 10 4 4 8-8"/>',
  moon:'<path d="M16.5 12A7 7 0 0 1 8 3a7.5 7.5 0 1 0 8.5 9Z"/>',
  battery:'<rect x="2" y="5" width="14" height="10" rx="2"/><path d="M18 8v4M5 8v4M8 8v4"/>',
  alert:'<path d="m10 2 9 16H1Z M10 7v4M10 14v.5"/>',
  folder:'<path d="M2 5h6l2 2h8v10H2Z"/>',
};
const svg = name => `<svg viewBox="0 0 20 20" aria-hidden="true">${icons[name] || icons.bookmark}</svg>`;
const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed = [
  [1,'How we find planets we cannot see','The Observatory','YouTube','Today','21:14','Video',18,['Space','Science'],'18m 24s','Edge'],
  [2,'The quiet geometry of Japanese gardens','Field Notes','YouTube','Today','20:32','Video',24,['Design','Places'],'9m 12s','Edge'],
  [3,'Midnight Diner: a table for one','Season 1, episode 4','Netflix','Today','19:46','Episode',25,['Food','Stories'],null,'Edge'],
  [4,'Building a tiny world, one pixel at a time','moss & pixels','Twitch','Today','18:05','Video',null,['Games','Art'],'26m 05s','Firefox'],
  [5,'A slower way to make coffee','Everyday Rituals','YouTube','Today','16:28','Video',9,['Food','Craft'],'6m 41s','Edge'],
  [6,'雨の日のピアノ — piano on a rainy afternoon','Room 203','Bilibili','Today','14:12','Video',42,['Music'],null,'Edge'],
  [7,'Why cities sound different at night','Small Hours','YouTube','Yesterday','22:08','Video',16,['Places','Sound'],'12m 08s','Firefox'],
  [8,'The art of noticing','Studio Journal','YouTube','Yesterday','20:51','Video',12,['Art','Design'],'8m 10s','Edge'],
  [9,'The last train home','Film study','Local files','Yesterday','19:06','Film',null,['Stories'],null,'Edge'],
  [10,'A kitchen at the edge of the world','Season 1, episode 2','Netflix','Yesterday','18:43','Episode',48,['Food','Places'],null,'Edge'],
  [11,'Sketchbook Sunday: drawing from memory','Pencil Club','Twitch','Yesterday','16:18','Video',null,['Art'],'4m 27s','Firefox'],
  [12,'The hidden mathematics of a good map','Field Notes','Earlier','Earlier','20:04','Video',21,['Design','Science'],'16m 11s','Edge'],
  [13,'A walk through the world’s smallest bookshops','Around the Corner','YouTube','Earlier','18:24','Video',14,['Places','Books'],'11m 18s','Firefox'],
  [14,'What a telescope actually sees','The Observatory','YouTube','Earlier','21:45','Video',11,['Space','Science'],'8m 15s','Edge'],
  [15,'Handmade: the ceramic cup','Everyday Rituals','Bilibili','Earlier','17:32','Video',19,['Craft','Art'],null,'Edge'],
  [16,'Watching the seasons change','A field recording','Local files','Earlier','15:10','Video',null,['Places','Sound'],null,'Firefox'],
  [17,'Inside a century-old animation studio: the craft, the notebooks, and the people who keep drawing','Studio Journal','YouTube','Earlier','13:26','Video',28,['Art','Design'],'20m 10s','Edge'],
  [18,'An evening in the mountains','Season 2, episode 1','Netflix','Earlier','19:28','Episode',46,['Places','Stories'],null,'Edge'],
].map(([id,title,author,platform,day,time,kind,duration,tags,tab,source]) => ({id,title,author,platform:platform==='Earlier'?'YouTube':platform,day,time,kind,duration,tags,tab,source}));
const state = {page:'history',mode:'populated',query:'',platform:'All platforms',date:'Any time',items:structuredClone(seed),saved:new Set(),budget:30,profiles:{edge:true,firefox:true,work:false},automation:false,theme:'night',density:'comfortable'};
const content = document.querySelector('#content');
const detail = document.querySelector('#detail');
const confirmation = document.querySelector('#confirmation');
let activeItem = null, lastOpener = null, pendingAction = null, toastTimer = null, undoAction = null;
const platformClass = p => ({YouTube:'youtube',Netflix:'netflix',Twitch:'twitch',Bilibili:'bilibili','Local files':'local'}[p]);
const platformIcon = p => `<span class="platform-icon ${platformClass(p)}">${p==='YouTube'?svg('play'):p==='Local files'?svg('folder'):p==='Netflix'?'N':p==='Twitch'?'t':'b'}</span>`;
function hydrate(){document.querySelectorAll('[data-icon]').forEach(e=>{e.innerHTML=svg(e.dataset.icon);});}
function items(){return state.mode==='empty'?[]:state.items;}
function notify(message, undo){clearTimeout(toastTimer);undoAction=undo || null;const el=document.querySelector('#toast');el.innerHTML=`<span>${escape(message)}</span>${undo?'<button data-action="undo">Undo</button>':''}`;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),6500);}
const headings = {history:['History','The things you opened. A little easier to find again.','Your library'],suggestions:['Suggestions','A few good reasons to return. All from your own library.','From your history'],sources:['Sources','Choose what belongs in your viewing history.','Your collection'],settings:['Settings','Make a little room for your preferences.','Your space']};
function render(){
  const [title,description,crumb]=headings[state.page];
  document.querySelector('#page-title').textContent=title;document.querySelector('#page-description').textContent=description;document.querySelector('#breadcrumb').textContent=crumb;
  document.querySelectorAll('[data-page]').forEach(b=>b.dataset.page===state.page?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current'));
  document.querySelector('#nav-count').textContent=items().length;
  ({history:history,suggestions:suggestions,sources:sources,settings:settings}[state.page])();hydrate();
}
function history(){
  content.innerHTML=`${state.mode==='partial'?`<div class="notice">${svg('alert')}<p>Firefox is busy. Your Edge history is available.</p><button data-page="sources">Review sources</button></div>`:''}
  <label class="searchbox">${svg('search')}<span class="sr-only">Search history</span><input id="search" type="search" placeholder="Find a title, creator, or topic…" value="${escape(state.query)}" autocomplete="off"><kbd>/</kbd></label>
  <div class="filterbar"><div class="filter-group"><label class="select-control"><span class="sr-only">Platform</span><select id="platform" aria-label="Platform">${['All platforms','YouTube','Netflix','Twitch','Bilibili','Local files'].map(p=>`<option ${p===state.platform?'selected':''}>${p}</option>`).join('')}</select></label><label class="select-control"><span class="sr-only">Date</span><select id="date" aria-label="Date">${['Any time','Today','Yesterday','Earlier'].map(p=>`<option ${p===state.date?'selected':''}>${p}</option>`).join('')}</select></label><button class="clear-filter" data-action="clear" ${!state.query&&state.platform==='All platforms'&&state.date==='Any time'?'hidden':''}>Clear filters</button></div><span id="result-count" class="result-count" aria-live="polite"></span></div><div id="history-results"></div>`;
  renderResults();
}
function renderResults(){
  const filtered=items().filter(i=>(state.platform==='All platforms'||i.platform===state.platform)&&(state.date==='Any time'||i.day===state.date)&&`${i.title} ${i.author} ${i.tags.join(' ')}`.toLowerCase().includes(state.query.toLowerCase()));
  document.querySelector('#result-count').textContent=`${filtered.length} ${filtered.length===1?'opening':'openings'}`;
  document.querySelector('[data-action="clear"]').hidden=!state.query&&state.platform==='All platforms'&&state.date==='Any time';
  document.querySelector('#history-results').innerHTML=filtered.length?['Today','Yesterday','Earlier'].map(day=>{const group=filtered.filter(i=>i.day===day);return group.length?`<section class="history-group" aria-label="${day}"><div class="day-heading"><h2>${day}</h2><span>${{Today:'3 November',Yesterday:'2 November',Earlier:'1 October'}[day]}</span><span class="day-count">${group.length} ${group.length===1?'opening':'openings'}</span></div>${group.map(row).join('')}</section>`:'';}).join(''):
  `<div class="empty">${svg(state.mode==='empty'?'bookmark':'search')}<h2>${state.mode==='empty'?'Your history starts here.':'No openings found.'}</h2><p>${state.mode==='empty'?'A small place for the videos you want to find again. Load the fictional library to explore this prototype.':'Try a different title or creator, or clear your filters to see the whole library.'}</p><button class="primary" data-action="${state.mode==='empty'?'load':'clear'}">${state.mode==='empty'?'Load sample library':'Clear filters'}</button></div>`;
}
function row(i){return `<button class="history-row" data-open="${i.id}" aria-label="View details: ${escape(i.title)}"><span class="row-time">${i.time}</span>${platformIcon(i.platform)}<span class="row-main"><span class="row-title">${escape(i.title)}</span><span class="row-sub"><span>${escape(i.author)}</span><span class="dot">/</span><span class="type-label">${i.kind}</span>${state.saved.has(i.id)?'<span class="saved-inline">Saved</span>':''}</span></span><span class="row-meta"><span class="row-platform">${i.platform}</span><span class="evidence-label"><span class="mobile-time">${i.time} / </span>Opened · ${i.source}</span></span><span class="row-arrow">${svg('arrow')}</span></button>`;}
function smallRow(i,reason){return `<button class="small-row" data-open="${i.id}">${platformIcon(i.platform)}<span><strong>${escape(i.title)}</strong><small>${escape(reason || i.author)}</small></span>${i.duration?`<span class="duration">${i.duration} min</span>`:svg('arrow')}</button>`;}
function suggestions(){
  const old=items().filter(i=>i.day==='Earlier').slice(0,2),fit=items().filter(i=>i.duration&&i.duration<=state.budget).sort((a,b)=>b.duration-a.duration).slice(0,3);
  content.innerHTML=`<div class="section-title"><h2>Rediscover</h2><p>Something you left a little while ago.</p></div>${old.length?`<div class="rediscover">${old.map(i=>`<button class="suggestion-card" data-open="${i.id}">${platformIcon(i.platform)}<h3>${escape(i.title)}</h3><p>${escape(i.author)} / ${i.platform}</p><span class="reason">Opened 33 days ago ${svg('arrow')}</span></button>`).join('')}</div>`:'<div class="unavailable"><h3>Nothing to rediscover yet</h3><p>Older openings will appear here after 30 days.</p></div>'}
  <div class="suggestion-bottom"><section><div class="section-title"><h2>Fits your time</h2><p>Known durations only</p></div><div class="budget" aria-label="Time budget">${[15,30,60].map(n=>`<button data-budget="${n}" aria-pressed="${n===state.budget}">${n} minutes</button>`).join('')}</div>${fit.length?fit.map(i=>smallRow(i,'Fits your selected time')).join(''):'<div class="unavailable"><p>No known durations fit this budget.</p></div>'}</section><section><div class="section-title"><h2>Continue watching</h2></div><div class="unavailable"><h3>A place for real progress.</h3><p>Opening a video doesn’t tell us how far you watched. This shelf will appear when playback measurements are available.</p></div><div class="section-title"><h2>Similar by topic</h2></div><label class="select-control">Based on<select id="similar-seed" aria-label="Similar by topic seed"><option value="1">The Observatory</option><option value="2">Field Notes</option><option value="5">Everyday Rituals</option></select></label><div id="similar-results"></div></section></div><p class="fine-print">Suggestions use fictional history and sample metadata in this prototype. No online recommendation service is connected.</p>`;
  renderSimilar(1);
}
function renderSimilar(id){const original=state.items.find(i=>i.id===id);const similar=items().filter(i=>i.id!==id&&i.tags.some(t=>original.tags.includes(t))).slice(0,2);document.querySelector('#similar-results').innerHTML=similar.length?similar.map(i=>smallRow(i,`Shared topic: ${i.tags.filter(t=>original.tags.includes(t)).join(', ')}`)).join(''):'<p class="fine-print">No shared topics in this library yet.</p>';}
function sources(){content.innerHTML=`<div class="section-title"><h2>Browser profiles</h2><p>${Object.values(state.profiles).filter(Boolean).length} selected in this preview</p></div><div class="source-list">${[['edge','E','Microsoft Edge','Personal','13 sample openings'],['firefox','F','Firefox','Default','5 sample openings'],['work','E','Microsoft Edge','Work','Excluded from collection']].map(([key,letter,name,profile,count])=>`<label class="source-row"><input type="checkbox" data-profile="${key}" ${state.profiles[key]?'checked':''} aria-label="Include ${name} ${profile}"><span class="browser-letter">${letter}</span><span class="source-info"><strong>${name}</strong><p>${profile} profile</p></span><span class="source-state ${!state.profiles[key]?'excluded':state.mode==='partial'&&key==='firefox'?'busy':''}">${!state.profiles[key]?'Excluded':state.mode==='partial'&&key==='firefox'?'Busy — retry later':key==='work'?'Included in preview':count}</span></label>`).join('')}</div><p class="fine-print">These profiles are examples. Changing a selection here does not access a browser or change your Omoi configuration.</p><section class="automation"><div class="automation-header"><div><h2>A quiet routine.</h2><p>Collect hourly and after you sign in. Omoi closes when the collection is done.</p></div><span class="state-pill">${state.automation?'Enabled in preview':'Not enabled'}</span></div><div class="automation-facts"><span>${svg('history')}Hourly + logon</span><span>${svg('battery')}Skip on battery</span><span>${svg('moon')}No waking your PC</span></div><button class="${state.automation?'secondary':'primary'}" data-action="automation">${state.automation?'Disable in preview':'Preview automatic collection'}</button><p class="fine-print">This control demonstrates the setup flow. It never installs a Windows task.</p></section>`;}
function settings(){content.innerHTML=`<section class="settings-section"><h2>Appearance</h2><div class="setting-row"><div><strong>Reading light</strong><p>A quiet night, a paper page, or a compact utility.</p></div><div class="segmented" aria-label="Theme">${[['night','Night'],['paper','Paper'],['panel','Panel']].map(([k,n])=>`<button data-theme="${k}" aria-pressed="${state.theme===k}">${n}</button>`).join('')}</div></div><p class="appearance-note">${{night:'Night keeps the violet and gold of Uika.',paper:'Paper takes its warm page, brick accent and square edges from Mariyaholic Confluence.',panel:'Panel follows the charcoal, gold and practical typography of your Mariyaholic desktop tools.'}[state.theme]}</p><div class="setting-row"><div><strong>List spacing</strong><p>Keep a little air, or fit more into the list.</p></div><div class="segmented" aria-label="List spacing">${[['comfortable','Comfortable'],['compact','Compact']].map(([k,n])=>`<button data-density="${k}" aria-pressed="${state.density===k}">${n}</button>`).join('')}</div></div></section><section class="settings-section"><h2>Your sample library</h2><div class="setting-row"><div><strong>Changes stay in this preview</strong><p>Saved items, removed entries and preferences reset when you reload.</p></div></div><div class="settings-actions"><button class="secondary" data-action="export">Export sample JSON</button><button class="secondary" data-action="reset">Reset preview</button></div><p class="fine-print">No account, browser connection or running collector. This is a local interface prototype, separate from the Omoi CLI.</p></section>`;}
function showDetail(id,opener){const item=state.items.find(i=>i.id===id);if(!item)return;activeItem=id;lastOpener=opener;renderDetail();if(!detail.open)detail.showModal();detail.querySelector('[data-action="close-detail"]').focus();}
function renderDetail(){const i=state.items.find(i=>i.id===activeItem);detail.innerHTML=`<div class="sheet-top"><span>From your history</span><button class="icon-button" data-action="close-detail" aria-label="Close details">${svg('close')}</button></div>${platformIcon(i.platform)}<h2 id="detail-title">${escape(i.title)}</h2><p class="detail-subtitle">${escape(i.author)} / ${i.platform}</p><div class="detail-evidence"><strong>${svg('history')} Opened in ${i.source}</strong><p>${i.tab?`Browser tab time: ${i.tab}. This is an approximation, not measured playback.`:'This browser record confirms an opening. Playback time and completion are unknown.'}</p></div><dl class="detail-list"><div><dt>Last opened</dt><dd>${i.day}, ${i.time}</dd></div><div><dt>Type</dt><dd>${i.kind}</dd></div><div><dt>Video duration</dt><dd>${i.duration?`${i.duration} minutes (sample metadata)`:'Unknown'}</dd></div><div><dt>Playback measured</dt><dd>Not available</dd></div></dl><div class="tags" aria-label="Sample topics">${i.tags.map(t=>`<span>${escape(t)}</span>`).join('')}</div><div class="detail-actions"><button class="primary" data-action="save">${svg(state.saved.has(i.id)?'check':'bookmark')}${state.saved.has(i.id)?'Saved for later':'Save for later'}</button><button class="secondary" data-action="remove">Remove from sample history</button></div><p class="detail-bottom">Fictional item for this interface study. Save and remove affect only this preview; there is no external video to open.</p>`;}
function ask(title,text,button,action,danger=false){pendingAction=action;confirmation.innerHTML=`<h2 id="confirm-title">${escape(title)}</h2><p>${escape(text)}</p><div class="confirm-actions"><button class="secondary" data-action="cancel">Cancel</button><button class="${danger?'danger-button':'primary'}" data-action="confirm">${escape(button)}</button></div>`;confirmation.showModal();confirmation.querySelector('[data-action="cancel"]').focus();}
function reset(){state.items=structuredClone(seed);state.saved.clear();state.query='';state.platform='All platforms';state.date='Any time';state.mode='populated';state.profiles={edge:true,firefox:true,work:false};state.automation=false;state.budget=30;state.theme='night';state.density='comfortable';document.body.removeAttribute('data-face');document.body.removeAttribute('data-skin');document.body.removeAttribute('data-density');document.querySelector('#preview-state').value='populated';render();notify('Preview reset. All sample entries restored.');}
const actions={
  refresh(){document.querySelector('#refresh').click();},
  clear(){state.query='';state.platform='All platforms';state.date='Any time';history();document.querySelector('#search').focus();},
  load(){state.mode='populated';document.querySelector('#preview-state').value='populated';render();},
  'close-detail'(){detail.close();},
  save(){state.saved.has(activeItem)?state.saved.delete(activeItem):state.saved.add(activeItem);renderDetail();render();detail.querySelector('[data-action="save"]').focus();},
  remove(){ask('Remove this opening?','This removes the entry from the fictional library. Your real history is never changed. You can undo this action.','Remove sample entry',()=>{const removed=state.items.find(i=>i.id===activeItem),index=state.items.indexOf(removed);state.items.splice(index,1);detail.close();render();document.querySelector('#main').focus();notify('Sample entry removed.',()=>{state.items.splice(index,0,removed);render();notify('Sample entry restored.');});},true);},
  cancel(){confirmation.close();pendingAction=null;},
  confirm(){confirmation.close();const action=pendingAction;pendingAction=null;action?.();},
  undo(){const action=undoAction;undoAction=null;action?.();},
  automation(){if(state.automation){state.automation=false;render();notify('Automatic collection disabled in preview.');}else ask('Preview automatic collection','In the app, this would create a per-user hourly and logon task that skips battery operation. Here, only the preview state changes.','Enable in preview',()=>{state.automation=true;render();notify('Enabled in preview only. No Windows task installed.');});},
  reset(){ask('Reset the preview?','Restore the fictional library and default appearance. All changes made in this preview will be cleared.','Reset preview',reset);},
  export(){const url=URL.createObjectURL(new Blob([JSON.stringify({fictional:true,items:items()},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='omoi-sample-library.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Exported fictional sample library.');},
};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){state.page=b.dataset.page;render();window.scrollTo(0,0);}else if(b.dataset.open){showDetail(Number(b.dataset.open),b);}else if(b.dataset.action){actions[b.dataset.action]?.();}else if(b.dataset.budget){state.budget=Number(b.dataset.budget);suggestions();}else if(b.dataset.theme){state.theme=b.dataset.theme;document.body.dataset.face=state.theme==='paper'?'sumimi':'doloris';document.body.dataset.skin=state.theme;settings();}else if(b.dataset.density){state.density=b.dataset.density;document.body.dataset.density=state.density;settings();}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();state.page='history';render();window.scrollTo(0,0);});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;renderResults();}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='platform'){state.platform=el.value;renderResults();}else if(el.id==='date'){state.date=el.value;renderResults();}else if(el.id==='preview-state'){state.mode=el.value;render();}else if(el.id==='similar-seed'){renderSimilar(Number(el.value));}else if(el.dataset.profile){state.profiles[el.dataset.profile]=el.checked;sources();document.querySelector(`[data-profile="${el.dataset.profile}"]`).focus();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!detail.open&&!confirmation.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();if(state.page!=='history'){state.page='history';render();}document.querySelector('#search').focus();}});
detail.addEventListener('close',()=>{if(lastOpener?.isConnected)lastOpener.focus();else document.querySelector(`[data-open="${activeItem}"]`)?.focus();});
document.querySelector('#refresh').addEventListener('click',()=>{const b=document.querySelector('#refresh'),mobile=document.querySelector('.mobile-refresh');b.disabled=true;mobile.disabled=true;b.innerHTML=`${svg('refresh')}Refreshing sample…`;setTimeout(()=>{b.disabled=false;mobile.disabled=false;b.innerHTML=`${svg('refresh')}Refresh sample`;document.querySelector('#collection-status').textContent='Sample refreshed just now';notify(state.mode==='partial'?'Edge sample refreshed. Firefox remains busy.':'Sample refreshed. No browser history accessed.');},650);});
render();
